BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS "OCORRENCIA" (
    "ID" INTEGER,
    "Numero_da_Ocorrencia" INTEGER NOT NULL,
    "Operador_Padronizado" TEXT,
    "Classificacao_da_Ocorrencia" TEXT,
    "Data_da_Ocorrencia" TEXT,
    "Hora_da_Ocorrencia" TEXT,
    "Historico" TEXT,
    "Fase_da_Operacao" TEXT,
    "Danos_a_Aeronave" TEXT,
    "Aerodromo_de_Destino" TEXT,
    "Aerodromo_de_Origem" TEXT,
    "PSSO" TEXT,
    "Operacao" TEXT,
    PRIMARY KEY("ID")
);

CREATE TABLE IF NOT EXISTS "ACIDENTE" (
    "ID" INTEGER,
    "Numero_da_Ficha" TEXT NOT NULL,
    "Lesoes_Fatais_Tripulantes" TEXT,
    "Lesoes_Fatais_Passageiros" TEXT,
    "Lesoes_Fatais_Terceiros" TEXT,
    "Lesoes_Graves_Tripulantes" TEXT,
    "Lesoes_Graves_Passageiros" TEXT,
    "Lesoes_Graves_Terceiros" TEXT,
    "Lesoes_Leves_Tripulantes" TEXT,
    "Lesoes_Leves_Passageiros" TEXT,
    "Lesoes_Leves_Terceiros" TEXT,
    "Ilesos_Tripulantes" TEXT,
    "Ilesos_Passageiros" TEXT,
    "Lesoes_Desconhecidas_Tripulantes" TEXT,
    "Lesoes_Desconhecidas_Passageiros" TEXT,
    "Lesoes_Desconhecidas_Terceiros" TEXT,
    FOREIGN KEY("ID") REFERENCES "OCORRENCIA"("ID"),
    PRIMARY KEY("ID")
);

CREATE TABLE IF NOT EXISTS "AERODROMO" (
    "ID" INTEGER,
    "ICAO" TEXT,
    "Tipo_de_Aerodromo" TEXT,
    FOREIGN KEY("ID") REFERENCES "OCORRENCIA"("ID"),
    PRIMARY KEY("ID")
);

CREATE TABLE IF NOT EXISTS "AERONAVE" (
    "ID" INTEGER,
    "Categoria_da_Aeronave" TEXT,
    "Modelo" TEXT,
    "CLS" TEXT,
    "PMD" TEXT,
    "Numero_de_Assentos" TEXT,
    "Nome_do_Fabricante" TEXT,
    "Tipo_ICAO" TEXT,
    FOREIGN KEY("ID") REFERENCES "OCORRENCIA"("ID"),
    PRIMARY KEY("ID")
);

CREATE TABLE IF NOT EXISTS "DESCRICAO" (
    "ID" INTEGER,
    "Descricao_do_Tipo" TEXT,
    "Tipo_de_Ocorrencia" TEXT,
    FOREIGN KEY("ID") REFERENCES "OCORRENCIA"("ID"),
    PRIMARY KEY("ID")
);

CREATE TABLE IF NOT EXISTS "LOCAL" (
    "ID" INTEGER,
    "Municipio" TEXT,
    "UF" TEXT,
    "Regiao" TEXT,
    "Latitude" TEXT,
    "Longitude" TEXT,
    FOREIGN KEY("ID") REFERENCES "OCORRENCIA"("ID"),
    PRIMARY KEY("ID")
);
